    private var logList: some View {
        ScrollViewReader { proxy in
            List {
                ForEach(model.visible) { entry in
                    row(entry)
                }
                // iOS 17 has no scroll-position API; a zero-height sentinel is how the
                // view learns whether the user is still parked at the tail.
                Color.clear
                    .frame(height: 1)
                    .listRowSeparator(.hidden)
